ALTER TABLE public.attempts ADD COLUMN resume_version integer NOT NULL DEFAULT 0, ADD COLUMN resume_allowed boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.teacher_resume_attempt() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='suspended' AND NEW.status='in_progress' THEN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.exams WHERE id=NEW.exam_id AND teacher_id=auth.uid()) THEN RAISE EXCEPTION 'Teacher approval required'; END IF; IF NEW.deadline_at <= now() THEN RAISE EXCEPTION 'Exam deadline passed'; END IF; NEW.resume_version := OLD.resume_version+1; NEW.resume_allowed := true; END IF; RETURN NEW; END $$;
CREATE TRIGGER teacher_resume_attempt BEFORE UPDATE ON public.attempts FOR EACH ROW EXECUTE FUNCTION public.teacher_resume_attempt();
CREATE OR REPLACE FUNCTION public.lock_exam_exit(_hash text, _type text, _version integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.attempts; BEGIN IF _type NOT IN ('tab_hidden','window_blur','exit_fullscreen','navigation','page_exit') THEN RAISE EXCEPTION 'Invalid event'; END IF; SELECT * INTO a FROM public.attempts WHERE token_hash=_hash FOR UPDATE; IF a.id IS NULL THEN RAISE EXCEPTION 'Invalid session'; END IF; IF a.status <> 'in_progress' OR a.resume_version <> _version THEN RETURN; END IF; INSERT INTO public.violations(attempt_id,exam_id,type) VALUES(a.id,a.exam_id,_type); UPDATE public.attempts SET status='suspended', violation_count=violation_count+1,resume_allowed=false WHERE id=a.id; END $$;
REVOKE ALL ON FUNCTION public.lock_exam_exit(text,text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.lock_exam_exit(text,text,integer) TO service_role;